import { describe, expect, it } from 'bun:test'
import { BaseError, GlobalErrorMapper, HttpStatusCode } from '@bk-dash/core-typescript'
import type { ApplicationErrors, DomainErrors, Errors, InfrastructureErrors, InterfaceErrors } from './index'
import './index'

describe('Integration context error glossary', () => {
	it('BaseError accepts an Integration domain code', () => {
		const err = new BaseError<Errors>('STORE_INTEGRATION_INACTIVE', 'cannot mutate inactive integration')
		expect(err.name).toBe('STORE_INTEGRATION_INACTIVE')
	})

	it('BaseError accepts an Integration application code', () => {
		const err = new BaseError<Errors>('PLATFORM_NOT_SUPPORTED')
		expect(err.name).toBe('PLATFORM_NOT_SUPPORTED')
	})

	it('BaseError accepts an Integration infrastructure code', () => {
		const err = new BaseError<Errors>('STORE_INTEGRATION_GO_WORKER_UNREACHABLE')
		expect(err.name).toBe('STORE_INTEGRATION_GO_WORKER_UNREACHABLE')
	})

	it('rejects unknown codes at compile time via union narrowing', () => {
		// @ts-expect-error — 'NOT_REAL_CODE' is not in the Errors union
		new BaseError<Errors>('NOT_REAL_CODE')
	})

	it('rejects Integration domain codes when typed as InterfaceErrors', () => {
		// @ts-expect-error — STORE_INTEGRATION_INACTIVE is DomainErrors, not InterfaceErrors
		new BaseError<InterfaceErrors>('STORE_INTEGRATION_INACTIVE')
	})

	it('rejects Integration application codes when typed as DomainErrors', () => {
		// @ts-expect-error — PLATFORM_NOT_SUPPORTED is ApplicationErrors, not DomainErrors
		new BaseError<DomainErrors>('PLATFORM_NOT_SUPPORTED')
	})

	it('rejects Integration infrastructure codes when typed as ApplicationErrors', () => {
		// @ts-expect-error — STORE_INTEGRATION_GO_WORKER_UNREACHABLE is InfrastructureErrors
		new BaseError<ApplicationErrors>('STORE_INTEGRATION_GO_WORKER_UNREACHABLE')
	})

	it('side-effect import registered every Integration code with GlobalErrorMapper', () => {
		const expected: [Errors, HttpStatusCode][] = [
			['PLATFORM_NOT_SUPPORTED', HttpStatusCode.BAD_REQUEST],
			['INVALID_CREDENTIAL_FIELDS', HttpStatusCode.BAD_REQUEST],
			['OAUTH_CODE_INVALID', HttpStatusCode.BAD_REQUEST],
			['INTEGRATION_HANDSHAKE_FAILED', HttpStatusCode.BAD_GATEWAY],
			['INTEGRATION_INSUFFICIENT_SCOPES', HttpStatusCode.FORBIDDEN],
			['INTEGRATION_MISSING_OAUTH_CODE', HttpStatusCode.BAD_REQUEST],
			['INTEGRATION_MISSING_CREDENTIALS', HttpStatusCode.BAD_REQUEST],
			['INTEGRATION_MISSING_CREDENTIAL_FIELD', HttpStatusCode.BAD_REQUEST],
			['INTEGRATION_QUOTA_EXCEEDED', HttpStatusCode.PAYMENT_REQUIRED],
			['STORE_INTEGRATION_NOT_FOUND', HttpStatusCode.NOT_FOUND],
			['STORE_INTEGRATION_INACTIVE', HttpStatusCode.CONFLICT],
			['STORE_INTEGRATION_ALREADY_DISCONNECTED', HttpStatusCode.CONFLICT],
			['REINTEGRATION_RATE_LIMITED', HttpStatusCode.TOO_MANY_REQUESTS],
			['STORE_INTEGRATION_CREDENTIAL_NOT_FOUND', HttpStatusCode.INTERNAL_SERVER_ERROR],
			['STORE_INTEGRATION_GO_WORKER_UNREACHABLE', HttpStatusCode.BAD_GATEWAY],
		]
		for (const [code, expectedStatus] of expected) {
			expect(GlobalErrorMapper[code]).toBe(expectedStatus)
		}
	})

	it('credential-decrypt failure rides on the core CREDENTIAL_DECRYPT_FAILED (no BC-specific alias)', () => {
		// Per iter-117 decision: core's vault throws CREDENTIAL_DECRYPT_FAILED;
		// this BC does NOT redefine a STORE_INTEGRATION_CREDENTIAL_DECRYPT_FAILED.
		// @ts-expect-error — not in the Integration Errors union (only core's CREDENTIAL_DECRYPT_FAILED is reachable, and that's BaseInfrastructureErrors here).
		new BaseError<Errors>('STORE_INTEGRATION_CREDENTIAL_DECRYPT_FAILED')

		// Core's code IS reachable through the InfrastructureErrors widening.
		const err = new BaseError<InfrastructureErrors>('CREDENTIAL_DECRYPT_FAILED')
		expect(err.name).toBe('CREDENTIAL_DECRYPT_FAILED')
	})
})
import { HttpStatusCode, registerErrorCodes } from '@bk-dash/core-typescript'
import type { BaseDomainErrors, BaseApplicationErrors, BaseInterfaceErrors, BaseInfrastructureErrors } from '@bk-dash/core-typescript'

// Per spec §7.14 BC3 base set.
export type IntegrationDomainErrors = 'STORE_INTEGRATION_ALREADY_DISCONNECTED' | 'STORE_INTEGRATION_INACTIVE' | 'INVALID_CREDENTIAL_FIELDS'
export type DomainErrors = BaseDomainErrors | IntegrationDomainErrors

export type IntegrationApplicationErrors =
	| 'PLATFORM_NOT_SUPPORTED'
	| 'STORE_INTEGRATION_NOT_FOUND'
	| 'STORE_INTEGRATION_CREDENTIAL_NOT_FOUND'
	| 'REINTEGRATION_RATE_LIMITED'
	| 'INTEGRATION_QUOTA_EXCEEDED'
	| 'INTEGRATION_ALREADY_CONNECTED'
	| 'NO_ACTIVE_INTEGRATIONS'
	| 'OAUTH_CODE_INVALID'
	| 'OAUTH_CODE_EXCHANGE_FAILED'
	| 'INTEGRATION_HANDSHAKE_FAILED'
	| 'INTEGRATION_INSUFFICIENT_SCOPES'
	| 'INTEGRATION_MISSING_OAUTH_CODE'
	| 'INTEGRATION_MISSING_CREDENTIALS'
	| 'INTEGRATION_MISSING_CREDENTIAL_FIELD'
	| 'CREDENTIAL_HANDLE_INVALID'
	| 'OAUTH_STATE_INVALID'
	| 'OAUTH_STATE_EXPIRED'
	| 'OAUTH_STATE_PLATFORM_MISMATCH'
	| 'OAUTH_USER_DENIED'
	| 'WEBHOOK_REGISTRATION_FAILED'
export type ApplicationErrors = BaseApplicationErrors | IntegrationApplicationErrors

// Note: STORE_INTEGRATION_CREDENTIAL_DECRYPT_FAILED was scoped per spec but
// merged into core's CREDENTIAL_DECRYPT_FAILED (iter 117) since the vault
// is core infrastructure shared across BCs. Callers throw the core variant.
export type IntegrationInfrastructureErrors = 'STORE_INTEGRATION_GO_WORKER_UNREACHABLE'
export type InfrastructureErrors = BaseInfrastructureErrors | IntegrationInfrastructureErrors

export type IntegrationInterfaceErrors = never
export type InterfaceErrors = BaseInterfaceErrors | IntegrationInterfaceErrors

export type Errors = ApplicationErrors | DomainErrors | InfrastructureErrors | InterfaceErrors

registerErrorCodes({
	PLATFORM_NOT_SUPPORTED: HttpStatusCode.BAD_REQUEST,
	INVALID_CREDENTIAL_FIELDS: HttpStatusCode.BAD_REQUEST,
	OAUTH_CODE_INVALID: HttpStatusCode.BAD_REQUEST,

