	static create(data: {
		storeId: string
		platform: PlatformProps
		externalId: string
		displayName: string
		ownerId: string
	}): StoreIntegration {
		// Validate the discriminated platform shape before deriving the id.
		PlatformSchema.parse(data.platform)

		const id = StoreIntegration.deterministicId(data.platform, data.externalId)
		return new StoreIntegration({
			id,
			storeId: data.storeId,
			type: data.platform.type,
			platform: data.platform.platform,
			externalId: data.externalId,
			displayName: data.displayName,
			credentialSecretId: null,
			// Born active: ConnectIntegration only reaches create once the handshake
			// has already cleared, so there is no pending/invalid state to model.
			active: true,
			connectedAt: new Date(),
			disconnectedAt: null,
			ownerId: data.ownerId,
		})
	}

	/** Attach the freshly-saved credential-secret row. Called after CredentialVault.seal + save. */
	attachCredentialSecret(secretId: string): void {
		this.credentialSecretId = new Id(secretId)
		this.validate()
	}

	/** User-initiated disconnect. Terminal — STORE_INTEGRATION_ALREADY_DISCONNECTED on retry. */
	disconnect(): void {
		if (this.disconnectedAt) {
			throw new BaseError<IntegrationDomainErrors>('STORE_INTEGRATION_ALREADY_DISCONNECTED')
		}
		this.disconnectedAt = new Date()
		this.active = false
		this.validate()
	}

	/** Soft toggle. Used by admin overrides + reintegration flows. */
	toggleActive(active: boolean): void {
		this.active = active
		this.validate()
	}
}

export interface StoreIntegration extends StoreIntegrationProps {}

