async findByStoreId(storeId: string, tx?: DrizzleClient): Promise<StoreIntegration[]> {
	const dbc = tx ?? this.db
	const result = await tryCatchAsync(async () => {
		return await dbc.select().from(storeIntegrations).where(eq(storeIntegrations.storeId, storeId))
	})
	if (!result.success) throw result.error
	return result.data.map(r => this.toDomain(r))
}

async findByStoreIdAndPlatform(storeId: string, platform: PlatformProps, tx?: DrizzleClient): Promise<StoreIntegration | undefined> {
	const dbc = tx ?? this.db
	const result = await tryCatchAsync(async () => {
		const rows = await dbc
			.select()
			.from(storeIntegrations)
			.where(
				and(
					eq(storeIntegrations.storeId, storeId),
					eq(storeIntegrations.type, platform.type),
					eq(storeIntegrations.platform, platform.platform),
				),
			)
			.limit(1)
		return rows[0]
	})
	if (!result.success || !result.data) return undefined
	return this.toDomain(result.data)
}

