import Z from 'zod'
import { injectable } from 'tsyringe-neo'
import { BaseError, CredentialVault, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { ConnectionMode } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegration } from '../entities/StoreIntegration'
import { IntegrationCredentialSecret } from '../entities/IntegrationCredentialSecret'
import { PlatformConnectBodySchema, PlatformConnectNonOAuthBodySchema, PlatformSchema } from '@integration/services'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../repositories/IntegrationCredentialSecretRepository'
import { HandshakeServiceFactory } from '../services/HandshakeService'
import { OAuthCodeExchangerFactory, type OAuthExchangeResult } from '../services/OAuthCodeExchanger'
import { CredentialsExchangerFactory } from '../services/CredentialsExchanger'
import { IntegrationActivatedEvent, IntegrationConnectionInitiatedEvent, IntegrationHandshakeSucceededEvent } from '../events'
import type { ApplicationErrors } from '../errors'

/**
 * Connect body — the SDK-exposed schema for POST /integrations. Narrowed to
 * non-OAuth modes (MANUAL / CREDENTIALS) so the OAuth leaf is physically
 * unreachable through HTTP: OAuth must go through the authorize → provider
 * → callback round-trip, which calls the use case in-process via DI.
 * (Spec Decision 10.)
 */
export const ConnectIntegrationBodySchema = PlatformConnectNonOAuthBodySchema

// Use-case input keeps the FULL union (incl. OAuth leaves) so the callback
// controller can pass OAuth bodies in-process via DI.
export const ConnectIntegrationInputSchema = PlatformConnectBodySchema.and(z.object({ storeId: z.uuid(), userId: z.uuid() }))
export type ConnectIntegrationInput = Z.infer<typeof ConnectIntegrationInputSchema>

export const ConnectIntegrationOutputSchema = z.object({
	storeIntegrationId: z.uuid(),
	active: z.boolean(),
	externalId: z.string(),
	displayName: z.string(),
})

/**
 * C21 ConnectIntegration. The discriminated input already validated the
 * (connectionMode, type, platform) coordinate and its credential fields, so the body
 * just dispatches: it resolves tokens + the canonical identifier via the
 * per-platform exchanger (OAuth or Manual), seals the tokens via the
 * CredentialVault, persists StoreIntegration + IntegrationCredentialSecret
 * atomically, and emits the domain-event sequence (Initiated →
 * Succeeded+Activated | Failed).
 *
 * OAuth platforms run the per-platform HandshakeService to confirm the
 * provider's canonical externalId; manual platforms have no handshake (SPEC-18)
 * — they activate directly on the exchanger-resolved identifier.
 *
 * The duplicate guard rejects re-connecting the SAME (storeId, type, platform)
 * tuple — to swap a connection, the merchant must Disconnect first.
 *
 * Errors surfaced verbatim to the controller; the response distinguishes
 * "handshake failed but row persisted as invalid" (200 with valid=false) from
 * "couldn't even reach handshake" (4xx/5xx).
 */
@injectable()
export class ConnectIntegration extends Handler<typeof ConnectIntegrationInputSchema, typeof ConnectIntegrationOutputSchema> {
	readonly name = 'connect_integration' as const
	readonly inputSchema = ConnectIntegrationInputSchema
	readonly outputSchema = ConnectIntegrationOutputSchema

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly credentialSecretRepo: IntegrationCredentialSecretRepository,
		private readonly handshakeFactory: HandshakeServiceFactory,
		private readonly oauthFactory: OAuthCodeExchangerFactory,
		private readonly credentialsFactory: CredentialsExchangerFactory,
		private readonly vault: CredentialVault,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		// input.type + input.platform are correlated *within* each union leaf, but
		// reading them off the un-narrowed union decorrelates them (TS widens to
		// { type: StoreIntegrationType; platform: <any platform> }), which isn't
		// assignable to the discriminated PlatformProps. Re-parse to recover the
		// correlated type — the values are already validated, so this only narrows.
		const platform = PlatformSchema.parse({ type: input.type, platform: input.platform })

		const existing = await this.storeIntegrationRepo.findByStoreIdAndPlatform(input.storeId, platform)
		if (existing !== undefined) {
			throw new BaseError<ApplicationErrors>('INTEGRATION_ALREADY_CONNECTED')
		}

		// Dispatch on connectionMode — narrowed by the discriminated union, so
		// input.oauthCode / input.credentials are present without `??` or guards.
		// Both exchangers return the canonical identifier + normalized tokens.
		const exchangeResult: OAuthExchangeResult =
			input.connectionMode === ConnectionMode.OAUTH
				? await this.oauthFactory.get(platform).exchange({ code: input.oauthCode, credentials: input.credentials })
				: await this.credentialsFactory.get(platform).exchange({ credentials: input.credentials })

		const { identifier, tokens: sealedPayload } = exchangeResult

		// OAuth platforms must clear the provider handshake before anything is
		// created. It runs here — outside the DB transaction (no network round-trip
		// inside an open tx) and as a hard gate: handshake() throws a named error
		// (INTEGRATION_HANDSHAKE_FAILED / INTEGRATION_INSUFFICIENT_SCOPES) on
		// rejection, which propagates to the controller and leaves no row or event
		// behind. Manual / credentials platforms have no handshake (SPEC-18) and
		// activate on the exchanger identifier.
		if (input.connectionMode === ConnectionMode.OAUTH) {
			await this.handshakeFactory.get(platform).handshake({ credentials: sealedPayload })
		}

		// Both gates passed — only now do we create (born active), persist, and publish.
		return this.withTransaction(tx, async tx => {
			const fallbackLabel = `${input.platform.toLowerCase()}:${identifier}`
			const initialDisplayName = exchangeResult.displayName ?? fallbackLabel
			const integration = StoreIntegration.create({
				storeId: input.storeId,
				platform,
				externalId: identifier,
				displayName: initialDisplayName,
				ownerId: input.userId,
			})

			const sealed = await this.vault.seal(sealedPayload)
			const secret = IntegrationCredentialSecret.create({
				storeIntegrationId: integration.id.value,
				sealed,
			})
			integration.attachCredentialSecret(secret.id.value)

			await this.storeIntegrationRepo.save(integration, tx)
			await this.credentialSecretRepo.save(secret, tx)

			const at = new Date()
			await this.domainEventRepository.saveMany(
				[
					new IntegrationConnectionInitiatedEvent({
						entityId: integration.id.value,
						ownerId: input.userId,
						payload: {
							storeIntegrationId: integration.id.value,
							type: input.type,
							platform: input.platform,
						},
					}),
					new IntegrationHandshakeSucceededEvent({
						entityId: integration.id.value,
						ownerId: input.userId,
						payload: { storeIntegrationId: integration.id.value, at },
					}),
					new IntegrationActivatedEvent({
						entityId: integration.id.value,
						ownerId: input.userId,
						payload: { storeIntegrationId: integration.id.value },
					}),
				],
				tx,
			)

			return {
				storeIntegrationId: integration.id.value,
				active: integration.active,
				externalId: identifier,
				displayName: integration.displayName,
			}
		})
	}
}

