import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { ConnectionMode, SalesPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'
import { ConnectIntegration, ConnectIntegrationBodySchema, type ConnectIntegrationInput } from './ConnectIntegration'
import { StoreIntegrationRepository } from '../repositories/StoreIntegrationRepository'
import { IntegrationCredentialSecretRepository } from '../repositories/IntegrationCredentialSecretRepository'
import { HandshakeServiceFactory, MockHandshakeService } from '../services/HandshakeService'
import { OAuthCodeExchangerFactory, MockOAuthCodeExchanger } from '../services/OAuthCodeExchanger'
import { IntegrationConnectionInitiatedEvent, IntegrationHandshakeSucceededEvent, IntegrationActivatedEvent } from '../events'

const STORE_ID = testId('store', '1')
const USER_ID = testId('user', '1')

describe('ConnectIntegration use case (C21)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: ConnectIntegration
	let storeIntegrationRepo: StoreIntegrationRepository
	let credentialSecretRepo: IntegrationCredentialSecretRepository
	let handshakeFactory: HandshakeServiceFactory
	let oauthFactory: OAuthCodeExchangerFactory

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(ConnectIntegration)
		storeIntegrationRepo = testBed.resolve(StoreIntegrationRepository)
		credentialSecretRepo = testBed.resolve(IntegrationCredentialSecretRepository)
		handshakeFactory = testBed.resolve(HandshakeServiceFactory)
		oauthFactory = testBed.resolve(OAuthCodeExchangerFactory)
	})
	beforeEach(async () => {
		await testBed.reset()
		// Mock repos are registered as singletons in the test container — clear
		// their in-memory state between tests so each spec starts from empty.

		// Mock services hold mutable error/result state between calls; reset.
		const mockHandshake = handshakeFactory.get({
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
		}) as MockHandshakeService
		mockHandshake.nextErrorReason = null
		const mockOAuth = oauthFactory.tryGet({
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
		}) as MockOAuthCodeExchanger
		mockOAuth.nextErrorReason = null
		mockOAuth.lastInput = null
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	const happyInput = {
		connectionMode: ConnectionMode.OAUTH,
		storeId: STORE_ID,
		userId: USER_ID,
		type: StoreIntegrationType.SALES_CHANNEL,
		platform: SalesPlatform.SHOPIFY,
		credentials: { shopDomain: 'acme.myshopify.com' },
		oauthCode: 'auth_code_abc',
	} satisfies ConnectIntegrationInput

	it('happy path: connects Shopify integration via OAuth → handshake succeeds → persists active', async () => {
		const result = await useCase.execute(happyInput)

		expect(result.active).toBe(true)
		// externalId is the exchanger-resolved identifier (Mock derives it from credentials.shopDomain).
		expect(result.externalId).toBe('acme.myshopify.com')
		// displayName comes from the exchanger (MockOAuthCodeExchanger default 'Mock Shop')
		expect(result.displayName).toBe('Mock Shop')

		const persisted = await storeIntegrationRepo.findById(result.storeIntegrationId)
		expect(persisted).toBeDefined()
		expect(persisted!.active).toBe(true)
		expect(persisted!.credentialSecretId).not.toBeNull()

		const secret = await credentialSecretRepo.findByStoreIntegrationId(result.storeIntegrationId)
		expect(secret).toBeDefined()
		expect(secret!.encryptionAlgorithm).toBe('aes-256-gcm-v1')
	})

	it('falls back to "<platform>:<identifier>" when the exchange supplies no label', async () => {
		const mockOAuth = oauthFactory.tryGet({
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
		}) as MockOAuthCodeExchanger
		mockOAuth.nextResult = {
			tokens: { accessToken: 'tk_no_label' },
		}
		const result = await useCase.execute(happyInput)
		expect(result.displayName).toBe('shopify:acme.myshopify.com')
	})

	it('emits IntegrationConnectionInitiated + Succeeded + Activated on success', async () => {
		const eventRepo = testBed.resolve(DomainEventRepository)
		await useCase.execute(happyInput)
		expect(await eventRepo.findByType(IntegrationConnectionInitiatedEvent)).toHaveLength(1)
		expect(await eventRepo.findByType(IntegrationHandshakeSucceededEvent)).toHaveLength(1)
		expect(await eventRepo.findByType(IntegrationActivatedEvent)).toHaveLength(1)
	})

	it('handshake failure: throws INTEGRATION_HANDSHAKE_FAILED and persists nothing (no row, no events)', async () => {
		const mockHandshake = handshakeFactory.get({
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
		}) as MockHandshakeService
		mockHandshake.nextErrorReason = 'simulated provider rejection'

		await expect(useCase.execute(happyInput)).rejects.toMatchObject({ name: 'INTEGRATION_HANDSHAKE_FAILED' })

		// The connection is gated on the handshake — a rejection leaves no row...
		const persisted = await storeIntegrationRepo.findByStoreIdAndPlatform(STORE_ID, {
			type: StoreIntegrationType.SALES_CHANNEL,
			platform: SalesPlatform.SHOPIFY,
		})
		expect(persisted).toBeUndefined()

		// ...and no events at all (nothing is published before both gates pass).
		const eventRepo = testBed.resolve(DomainEventRepository)
		expect(await eventRepo.findByType(IntegrationConnectionInitiatedEvent)).toHaveLength(0)
		expect(await eventRepo.findByType(IntegrationHandshakeSucceededEvent)).toHaveLength(0)
